<?php
require __DIR__.'/../lib/lms.php';require __DIR__.'/../lib/notify.php';require __DIR__.'/../lib/rewards.php';require __DIR__.'/../lib/oauth.php';$p=require_parent();
if(($_POST['action']??'')==='notify'){ // phụ huynh tự đăng ký nhận tin (đồng ý), có thể tắt bất cứ lúc nào
 $ch=$_POST['channel']??'none';$phone=normalize_phone((string)($_POST['phone']??''));
 if($ch!=='none'&&!isset(notify_channels()[$ch]))flash('Kênh này chưa được nhà trường bật.','bad');
 elseif($ch!=='none'&&!$phone)flash('Số điện thoại di động Việt Nam 10 số, VD 0912345678.','bad');
 else{q('UPDATE parents SET phone=?,notify_channel=? WHERE id=?',[$ch==='none'?null:$phone,$ch,$p['id']]);flash($ch==='none'?'Đã tắt nhận tin.':'Đã đăng ký nhận tin qua '.NOTIFY_CHANNELS[$ch].'.');}
 redirect('home.php');
}
if($_SERVER['REQUEST_METHOD']==='POST')try{
 db()->beginTransaction();$i=q1('SELECT * FROM parent_invites WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() FOR UPDATE',[hash('sha256',trim($_POST['invite']??''))]);if(!$i||!qv('SELECT 1 FROM students WHERE class_id=? AND student_code=?',[$i['class_id'],$i['student_code']]))throw new RuntimeException('Mã mời không hợp lệ.');q('INSERT IGNORE INTO parent_links(parent_id,student_code,class_id) VALUES(?,?,?)',[$p['id'],$i['student_code'],$i['class_id']]);q('UPDATE parent_invites SET used_at=NOW() WHERE id=?',[$i['id']]);db()->commit();redirect('home.php');
}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash($e->getMessage(),'bad');}
$children=qall('SELECT st.*,c.name AS class_name FROM parent_links l JOIN students st ON st.student_code=l.student_code AND st.class_id=l.class_id JOIN classes c ON c.id=l.class_id WHERE l.parent_id=? ORDER BY st.full_name,c.name',[$p['id']]);
parent_head('Tiến độ của con');echo '<h1>Tiến độ của con</h1><form method="post">'.csrf_field().'<label>Liên kết thêm con/lớp bằng mã mời<input name="invite" required></label><button>Liên kết</button></form>';
$pp=q1('SELECT phone,notify_channel FROM parents WHERE id=?',[$p['id']]);$chs=notify_channels();
if($chs){echo '<form method="post" class="card row">'.csrf_field().'<input type="hidden" name="action" value="notify"><b>📨 Nhận kết quả buổi học</b><select name="channel"><option value="none">Không nhận</option>';foreach($chs as $k=>$v)echo '<option value="'.$k.'"'.($pp['notify_channel']===$k?' selected':'').'>Qua '.h($v).'</option>';echo '</select><input name="phone" inputmode="tel" placeholder="09xxxxxxxx" value="'.h($pp['phone']??'').'"><button>Lưu</button><span class="muted small">Sau mỗi buổi học thầy cô công bố, bạn nhận tin dạng “cháu trả lời đúng 8/10 câu hỏi bằng Remote”.</span></form>';}
foreach($children as $child){$code=$child['student_code'];$cid=(int)$child['class_id'];$items=my_items($code,$cid);$topics=[];$sessions=[];
 foreach($items as $r){$tp=$r['topic']?:'Chưa gắn chủ đề';$topics[$tp]??=['n'=>0,'ok'=>0];if($r['status']!=='absent'){$topics[$tp]['n']++;$topics[$tp]['ok']+=(int)($r['status']==='right');}}
 $pts=null;foreach(class_points($cid) as $row)if($row['code']===$code)$pts=$row;
 echo '<section class="card"><h2>'.h($child['full_name']).' · '.h($child['class_name']).'</h2>'.($pts?'<p>🏆 Điểm thi đua: <b data-count="'.$pts['points'].'">'.$pts['points'].'</b> · hạng '.$pts['rank'].' trong lớp ('.$pts['remote'].' câu Remote đúng)</p>':'').'<h3>Điểm và chuyên cần trên lớp</h3><table class="grid"><tr><th>Ngày / đề</th><th>Có mặt</th><th>Điểm / 10</th></tr>';
 // Attendance uses actual login, including sessions with no graded questions.
 $session_rows=qall('SELECT s.id,s.started_at,qs.title,(SELECT COUNT(*) FROM session_logins l WHERE l.session_id=s.id AND l.seat_no=?) AS present,(SELECT COUNT(*) FROM session_questions sq JOIN questions q ON q.id=sq.question_id WHERE sq.session_id=s.id AND q.correct IS NOT NULL) AS n,(SELECT COUNT(*) FROM final_answers f JOIN session_questions sq ON sq.id=f.session_q_id JOIN questions q ON q.id=sq.question_id WHERE sq.session_id=s.id AND f.seat_no=? AND f.answer=q.correct) AS ok FROM sessions s JOIN question_sets qs ON qs.id=s.set_id WHERE s.class_id=? AND s.status="ended" AND s.released=1 ORDER BY s.started_at DESC',[$child['seat_no'],$child['seat_no'],$cid]);foreach($session_rows as $r)echo '<tr><td>'.h($r['started_at'].' · '.$r['title']).'</td><td>'.($r['present']?'Có':'Vắng').'</td><td>'.($r['present']&&$r['n']?round(10*$r['ok']/$r['n'],1):'—').'</td></tr>';echo '</table><h3>Tiến độ theo ngày / tuần</h3><form method="get"><select name="period"><option value="day">Theo ngày</option><option value="week" '.(($_GET['period']??'')==='week'?'selected':'').'>Theo tuần</option></select><button>Xem</button></form>';echo parent_progress($session_rows,($_GET['period']??'')==='week'?'week':'day');
 echo '<h3>Bài tập về nhà</h3>';foreach(qall('SELECT h.title,s.submitted_at,s.released,s.id FROM homework h LEFT JOIN homework_submissions s ON s.homework_id=h.id AND s.student_code=? WHERE h.class_id=? AND h.published=1 ORDER BY h.id DESC',[$code,$cid]) as $r){$score=$r['released']?q1('SELECT SUM(a.score) AS score,SUM(hq.max_score) AS max_score FROM homework_answers a JOIN homework_questions hq ON hq.id=a.hw_question_id WHERE a.submission_id=?',[$r['id']]):null;echo '<p>'.h($r['title']).' · '.($r['submitted_at']?'Đã nộp':'Chưa nộp').($score?' · '.h($score['score']).'/'.h($score['max_score']):'').'</p>';}
 echo '<h3>Kiến thức trên lớp</h3>';foreach($topics as $tp=>$v){$pct=$v['n']?round(100*$v['ok']/$v['n']):0;echo '<p>'.h($tp).' · '.$pct.'% ('.$v['n'].' câu)</p><progress data-animate value="'.$pct.'" max="100" style="width:100%"></progress>';}
 echo '<h3>Nhận xét giáo viên</h3>';foreach(qall('SELECT tc.*,t.full_name FROM teacher_comments tc JOIN teachers t ON t.id=tc.teacher_id WHERE tc.class_id=? AND tc.student_code=? ORDER BY tc.id DESC',[$cid,$code]) as $r)echo '<blockquote>'.nl2br(h($r['comment'])).'<small> — '.h($r['full_name'].' · '.$r['created_at']).'</small></blockquote>';
 echo '<h3>Tài liệu bài giảng</h3>';foreach(qall('SELECT id,no,title FROM lessons WHERE class_id=? AND published=1 AND file_store IS NOT NULL ORDER BY no',[$cid]) as $r)echo '<p><a href="../file.php?lesson='.$r['id'].'">'.h(lesson_label($r)).'</a></p>';echo '</section>';
}
if($om=oauth_manage_html('parent',(string)$p['id'],'../'))echo '<section class="card" id="account">'.$om.'</section>';
page_foot();
